/* @lc app=leetcode id=2081 lang=kotlin */ class Solution { fun kMirror(k: Int, n: Int): Long = generateSequence(1L) { it + 1 }.flatMap { len -> (java.lang.Math.pow(10.0, ((len - 1) / 2).toDouble()).toLong() until java.lang.Math.pow(10.0, ((len + 1) / 2).toDouble()).toLong()).asSequence().map { h -> h.toString().let { it + it.dropLast((len % 2).toInt()).reversed() }.toLong() } }.filter { it.toString(k).let { s -> s == s.reversed() } }.take(n).sum() }